def maximum_row_limited_grid_sum(grid,limits,k):
    import heapq
    chosen=[]
    for row,limit in zip(grid,limits):
        for value in sorted(row,reverse=True)[:limit]:
            heapq.heappush(chosen,value)
            if len(chosen)>k:heapq.heappop(chosen)
    return sum(chosen)

